@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    @Mock
    private OrderRepository orderRepository;
    @Mock
    private PaymentService paymentService;

    @InjectMocks
    private OrderService orderService;  // Mockito calls constructor with both mocks

    @Test
    void shouldProcessOrder() {
        var order = new Order(1L, "Laptop", 999.99);
        when(orderRepository.save(any())).thenReturn(order);
        when(paymentService.charge(999.99)).thenReturn(true);

        var result = orderService.processOrder(order);  // Uses injected mocks

        assertThat(result).isTrue();
        verify(orderRepository).save(order);  // Verifies mock interaction
    }
}

@Service
public class OrderService {
    private final OrderRepository orderRepository;
    private final PaymentService paymentService;  // final = immutable after construction

    public OrderService(OrderRepository orderRepository, 
                       PaymentService paymentService) {  // No @Autowired needed in modern Spring
        this.orderRepository = orderRepository;
        this.paymentService = paymentService;
    }

    public boolean processOrder(Order order) {
        var savedOrder = orderRepository.save(order);
        return paymentService.charge(order.amount());
    }
}

