@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    @Mock
    private OrderRepository orderRepository;
    @Mock
    private PaymentService paymentService;
    @Mock
    private NotificationService notificationService;

    private OrderService orderService;  // No @InjectMocks — we control it

    @BeforeEach
    void setUp() {
        orderService = new OrderService(orderRepository, paymentService, notificationService);
    }

    @Test
    void shouldProcessOrderWithNotification() {
        var order = new Order(1L, "Laptop", 999.99);
        when(orderRepository.save(any())).thenReturn(order);

        orderService.processOrder(order);  // Explicit wiring, no surprises

        verify(notificationService).sendConfirmation(order);
    }
}

