class OrderService {
    private final OrderRepository orderRepository;
    private final PaymentService paymentService;
    private final NotificationService notificationService;

    // Largest constructor — Mockito will use this if all mocks are available
    public OrderService(OrderRepository repo, PaymentService payment, NotificationService notify) {
        this.orderRepository = repo;
        this.paymentService = payment;
        this.notificationService = notify;
    }

    // Smaller constructor — only used if NotificationService mock is missing
    public OrderService(OrderRepository repo, PaymentService payment) {
        this(repo, payment, null);  // Fallback constructor
    }
}

