@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    @Mock
    private OrderRepository orderRepository;
    @Mock
    private PaymentService paymentService;
    @Mock
    private NotificationService notificationService;

    private OrderService orderService;  // Not annotated — we control it

    @BeforeEach
    void setUp() {
        orderService = new OrderService(
            orderRepository,
            paymentService,
            notificationService
        );  // Explicit wiring — compile-time safety
    }

    @Test
    void shouldProcessOrderSuccessfully() {
        var order = new Order(1L, "Laptop", 999.99);
        when(orderRepository.save(any())).thenReturn(order);
        when(paymentService.charge(999.99)).thenReturn(true);

        var result = orderService.processOrder(order);

        assertThat(result).isTrue();
        verify(notificationService).sendConfirmation(order);
    }
}

