// INTEGRATION TEST — Spring context loaded
@WebMvcTest(OrderController.class)  // Loads web layer only, not full app
class OrderControllerIntegrationTest {
    @Autowired
    private MockMvc mockMvc;  // Injected by Spring

    @MockBean
    private OrderService orderService;  // Replaces real OrderService with mock

    @Test
    void shouldReturnOrders() throws Exception {
        when(orderService.findAll()).thenReturn(List.of());
        mockMvc.perform(get("/orders"))
               .andExpect(status().isOk())
               .andExpect(jsonPath("$").isEmpty());
    }
}
